ALTER TABLE "issues" ADD CONSTRAINT "issues_takedown_check" CHECK (("issues"."taken_down_at" IS NULL) = ("issues"."takedown_reason" IS NULL) AND ("issues"."takedown_reason" IS NULL OR "issues"."takedown_reason" IN ('standard_1', 'standard_2', 'standard_3', 'standard_4', 'standard_5', 'standard_6', 'standard_7', 'standard_8', 'standard_9', 'standard_10', 'standard_11', 'standard_12', 'standard_13', 'komdigi_order', 'data_subject_request')) AND ("issues"."taken_down_at" IS NULL OR "issues"."published_at" IS NULL)) NOT VALID;--> statement-breakpoint
ALTER TABLE "moderation_decisions" ADD CONSTRAINT "moderation_decisions_reason_check" CHECK (("moderation_decisions"."action" = 'verify' AND "moderation_decisions"."reason_code" IN ('document', 'site_photo', 'second_party', 'news_source', 'reporter_contact') AND "moderation_decisions"."reason_text" IS NULL) OR ("moderation_decisions"."action" = 'reject' AND "moderation_decisions"."reason_code" IN ('standard_1', 'standard_2', 'standard_3', 'standard_4', 'standard_5', 'standard_6', 'standard_7', 'standard_8', 'standard_9', 'standard_10', 'standard_11', 'standard_12', 'standard_13', 'out_of_scope') AND "moderation_decisions"."reason_text" IS NOT NULL) OR ("moderation_decisions"."action" = 'mark_unverifiable' AND "moderation_decisions"."reason_code" IN ('no_evidence', 'source_unreachable', 'conflicting_information', 'location_unclear') AND "moderation_decisions"."reason_text" IS NOT NULL)) NOT VALID;